import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.DYAmjhAm.js";const p=JSON.parse('{"title":"Performance vs 2.x","description":"","frontmatter":{},"headers":[],"relativePath":"guide/performance-vs-2x.md","filePath":"guide/performance-vs-2x.md","lastUpdated":1789863754000}'),i={name:"guide/performance-vs-2x.md"};function n(d,t,o,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="performance-vs-2-x" tabindex="-1">Performance vs 2.x <a class="header-anchor" href="#performance-vs-2-x" aria-label="Permalink to &quot;Performance vs 2.x&quot;">​</a></h1><p>3.0 is a rewrite of the same design, not a new one: the same cache, the same change tracking, the same materialization path. So the interesting question about the rewrite is whether it costs less to run, and the answer is mostly yes — a cached entity takes <strong>half the memory</strong> it did, and the paths an application spends its time in are 1.2× to 1.6× quicker.</p><p>This page compares 3.0.0 against 2.2.2. For what an individual operation costs in absolute terms, and which options to reach for when a screen is slow, see <a href="/breeze-client-v3/guide/performance">Performance</a>.</p><h2 id="what-got-faster" tabindex="-1">What got faster <a class="header-anchor" href="#what-got-faster" aria-label="Permalink to &quot;What got faster&quot;">​</a></h2><p>Each measurement runs the same payload against both versions and ends with the same cache.</p><table tabindex="0"><thead><tr><th>measurement</th><th style="text-align:right;">2.2.2</th><th style="text-align:right;">3.0.0</th><th></th></tr></thead><tbody><tr><td><code>importMetadata</code>, 21 types</td><td style="text-align:right;">4.1 ms</td><td style="text-align:right;">3.6 ms</td><td>1.15×</td></tr><tr><td>query: materialize 5,000 entities</td><td style="text-align:right;">111 ms</td><td style="text-align:right;">77 ms</td><td><strong>1.4×</strong></td></tr><tr><td>query: merge 5,000 already-cached entities</td><td style="text-align:right;">32 ms</td><td style="text-align:right;">25 ms</td><td>1.3×</td></tr><tr><td>query with expand: 1,000 parents + 5,000 children</td><td style="text-align:right;">171 ms</td><td style="text-align:right;">112 ms</td><td><strong>1.5×</strong></td></tr><tr><td><code>createEntity</code> × 5,000</td><td style="text-align:right;">124 ms</td><td style="text-align:right;">78 ms</td><td><strong>1.6×</strong></td></tr><tr><td>set a tracked property × 5,000</td><td style="text-align:right;">7.2 ms</td><td style="text-align:right;">3.2 ms</td><td>2.2×</td></tr><tr><td><code>executeQueryLocally</code> over 5,000 entities</td><td style="text-align:right;">2.6 ms</td><td style="text-align:right;">1.6 ms</td><td>1.7×</td></tr><tr><td><code>getEntityByKey</code> × 5,000</td><td style="text-align:right;">1.6 ms</td><td style="text-align:right;">0.9 ms</td><td>1.7×</td></tr><tr><td><code>validateEntity</code> × 5,000</td><td style="text-align:right;">54 ms</td><td style="text-align:right;">47 ms</td><td>1.2×</td></tr><tr><td><code>exportEntities</code>, 5,000 entities</td><td style="text-align:right;">33 ms</td><td style="text-align:right;">32 ms</td><td>—</td></tr><tr><td><code>importEntities</code>, 5,000 entities</td><td style="text-align:right;">114 ms</td><td style="text-align:right;">77 ms</td><td><strong>1.5×</strong></td></tr><tr><td><code>em.clear()</code>, 5,000 entities</td><td style="text-align:right;">2.5 ms</td><td style="text-align:right;">0.6 ms</td><td>4.4×</td></tr></tbody></table><p>Nothing here needed a change in your code. The gains come from the rewrite itself — native classes and prototype accessors in place of per-instance closures, <code>Map</code> and <code>Set</code> in place of object literals used as dictionaries, and <code>for</code> loops on the hot paths.</p><p>Queries and <code>importEntities</code> are where most applications will notice it, because those are the operations that run over thousands of rows at once.</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p>A cached entity is half the size it was:</p><table tabindex="0"><thead><tr><th></th><th style="text-align:right;">2.2.2</th><th style="text-align:right;">3.0.0</th></tr></thead><tbody><tr><td>per cached <code>Order</code></td><td style="text-align:right;">4.58 KB</td><td style="text-align:right;"><strong>2.38 KB</strong></td></tr><tr><td>a cache of 20,000</td><td style="text-align:right;">87.0 MB</td><td style="text-align:right;"><strong>44.9 MB</strong></td></tr></tbody></table><p>This is the largest single difference between the versions, and it is the one that changes what is possible rather than merely how fast it is: a 20,000-row cache that used to be uncomfortable on a modest device now is not. Two things account for most of it — an entity&#39;s properties are accessors on the prototype rather than closures created per instance, and <a href="/breeze-client-v3/guide/performance#collections-are-created-on-first-read">collection navigations are created on first read</a> rather than eagerly for every entity.</p><h2 id="bundle-size" tabindex="-1">Bundle size <a class="header-anchor" href="#bundle-size" aria-label="Permalink to &quot;Bundle size&quot;">​</a></h2><p>3.0 tree-shakes and 2.2 does not. In 2.2, importing only <code>MetadataStore</code>, only <code>Predicate</code> or the whole <code>EntityManager</code> produced byte-identical bundles — nothing was ever dropped. In 3.0 the parts are separable:</p><table tabindex="0"><thead><tr><th>what the application imports</th><th style="text-align:right;">2.2.2</th><th style="text-align:right;">3.0.0</th></tr></thead><tbody><tr><td><code>MetadataStore</code> only</td><td style="text-align:right;">48.5 KB</td><td style="text-align:right;"><strong>37.9 KB</strong></td></tr><tr><td><code>EntityManager</code></td><td style="text-align:right;">48.5 KB</td><td style="text-align:right;">53.3 KB</td></tr><tr><td>a typical app: <code>EntityManager</code> + the four standard adapters</td><td style="text-align:right;">51.2 KB</td><td style="text-align:right;">53.3 KB</td></tr></tbody></table><p>Minified and gzipped. The catch is in the second row: importing <code>EntityManager</code> in 3.0 also brings in the four default adapters, because it registers them so that a manager works without any configuration. That is why the last two rows are the same figure, and why a typical application — which registers those adapters anyway — pays about <strong>4% more</strong> than it did under 2.2. An application that uses Breeze&#39;s metadata without its cache pays a fifth less.</p><div class="warning custom-block"><p class="custom-block-title">A 2.x bundling bug that 3.0 fixes</p><p>Because 2.x declared itself entirely side-effect free, a production build <strong>silently dropped</strong><code>import &#39;breeze-client/mixin-get-entity-graph&#39;</code>, leaving <code>getEntityGraph</code> undefined at runtime while working in development. 3.0 names that file as its one side-effectful module, so it survives bundling. See <a href="/breeze-client-v3/guide/extensions#entity-graphs">Optional extensions</a>.</p></div><h2 id="where-3-0-is-slower" tabindex="-1">Where 3.0 is slower <a class="header-anchor" href="#where-3-0-is-slower" aria-label="Permalink to &quot;Where 3.0 is slower&quot;">​</a></h2><p><strong>Importing the library unbundled</strong>: 21 ms under 2.2, 54 ms under 3.0. 3.0 ships 48 separate ESM modules where 2.2 shipped one pre-flattened file, so it pays Node&#39;s per-file resolution cost. This is what makes the tree-shaking above possible, and it disappears once the code is bundled — booting the bundled library takes the same time in both. It is worth knowing about only for Node and SSR, or an unbundled dev server; a built browser application never sees it.</p><h2 id="how-these-were-measured" tabindex="-1">How these were measured <a class="header-anchor" href="#how-these-were-measured" aria-label="Permalink to &quot;How these were measured&quot;">​</a></h2><p>Node 24, 3.0.0 packed from <code>dist/</code> and 2.2.2 installed from npm, each in its own process, five alternating rounds with the best median taken. Both versions are driven through the same benchmark against the same Northwind metadata, with a fake transport that answers instantly from a fixed payload, so nothing measured includes network or JSON parsing.</p><p>The two runs are checked against each other before they are compared: same number of entities materialized, same local-query hit count, same number of changes, same exported byte count. A difference there would mean the versions had not done the same work, and the timings would be meaningless.</p><p>Bundles were built with Vite 8 targeting <code>es2022</code>, from each version as an installed package. Absolute bundle figures move with the bundler and its settings — treat the comparison between the columns as the durable part, not the numbers themselves. The same caution applies to the timings: ratios survive a change of machine, milliseconds do not.</p>',23)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
